var countQuadruples = function(firstString, secondString) {
    const first = Array(26).fill(-1);
    for (let i = 0; i < firstString.length; ++i) {
        const c = firstString.charCodeAt(i) - 97;
        if (first[c] === -1) first[c] = i;
    }

    const last = Array(26).fill(-1);
    for (let j = 0; j < secondString.length; ++j) {
        last[secondString.charCodeAt(j) - 97] = j;
    }

    let minDiff = Infinity;
    let ans = 0;
    for (let c = 0; c < 26; ++c) {
        if (first[c] !== -1 && last[c] !== -1) {
            const diff = first[c] - last[c];
            if (diff < minDiff) {
                minDiff = diff;
                ans = 1;
            } else if (diff === minDiff) {
                ans++;
            }
        }
    }
    return ans;
};
